// A mobile reservation list with desktop table
export function ReservationTableDesktop( { rows, onEdit, onCancel } ) {
  return (
    <div className="mt-6 grid grid-cols-1 gap-6 sm:grid-cols-2">
      <table className="hidden w-full text-sm md:table">
        <thead><tr><th>Room</th><th>Title</th><th>Organizer</th><th>Start</th><th>End</th><th>Status</th><th>Actions</th></tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.id}>
              <td>{r.roomName}</td><td>{r.title}</td><td>{r.organizer}</td>
              <td>{r.start}</td><td>{r.end}</td>
              <td>{r.status}</td>
              <td>
                <button onClick={() => onEdit(r.id)}>Edit</button>
                <button onClick={() => onCancel(r.id)}>Cancel</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <ul className="space-y-2 md:hidden">
        {rows.map((r) => (
          <li key={r.id} className="rounded-md border p-3">
            <p className="font-medium">{r.title}</p>
            <p className="text-sm text-muted-foreground">{r.organizer} · {r.start} - {r.end}</p>
            <div className="mt-2 flex gap-2">
              <button onClick={() => onEdit(r.id)}>Edit</button>
              <button onClick={() => onCancel(r.id)}>Cancel</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  )
}

